import {productionIntent,productionPreferences,preferencesFromReply} from './production-core.js';
import {runLocalTranscription} from './transcription-runner.js';
const el=(tag,text='')=>{const n=document.createElement(tag);n.textContent=text;return n;};
export function mountProduction(api){let busy=false,controller;
 const update=(id,patch)=>{const m=api.getState().messages.find(m=>m.id===id);if(m)Object.assign(m,patch);api.save()};
 function queue(text){const request=productionIntent(text);if(!request)return false;for(const m of api.getState().messages)if(m.production?.status==='pending'){m.production.status='done';m.text='Заменено новой задачей.'}const match=text.match(/(\d{1,3})\s*(?:сек|sec)/i),preferences=preferencesFromReply(text,{duration:match?Number(match[1]):api.getState().targetDuration});api.getState().messages.push({id:crypto.randomUUID(),role:'user',text},{id:crypto.randomUUID(),role:'assistant',text:request.kind==='script'?'Сделаю монтаж, придумаю рекламный текст и размещу его титрами — это не распознавание речи. Уточните оформление и что рекламируем.':'В каком стиле оформить речь? Выберите язык, цвет и положение. После ответа запущу распознавание прямо здесь.',production:{request,preferences,status:'pending'}});api.clearInput();api.render();api.save();return true;}
 async function execute(id,preferences){if(busy||!api.creationAllowed())return;const message=api.getState().messages.find(m=>m.id===id),job=message?.production;if(!job||job.status==='done')return;busy=true;controller=new AbortController();update(id,{production:{...job,preferences,status:'running'},text:job.request.kind==='script'?'ИИ готовит монтаж, рекламный текст и оформление обложки…':'Начинаю распознавание речи…'});api.render();try{api.pause();api.ensureTimeline();if(job.request.kind==='speech'){const count=await runLocalTranscription(api,preferences,text=>{const node=document.querySelector(`[data-production-status="${id}"]`);if(node)node.textContent=text},controller.signal);update(id,{text:`Готово: ${count} реплик из речи. Оформление применено; текст и время можно поправить во вкладке «Субтитры».`,production:{...job,preferences,status:'done'}})}else{const result=await api.generate(job.request,preferences,controller.signal);if(controller.signal.aborted)throw Error('Задача остановлена');if(!await api.apply(result,preferences))throw Error('Монтаж не применён. Проверьте ответ модели.');update(id,{text:'Готово: монтаж и рекламные титры применены. Макет обложки сохранён — откройте его для просмотра и скачивания PNG.',production:{...job,preferences,status:'done'},cover:api.getState().cover,plan:undefined});}}catch(e){update(id,{text:e.name==='AbortError'?'Задача остановлена.':'Задача не завершена: '+e.message,production:{...job,preferences,status:'pending'}})}finally{busy=false;controller=null;api.render();api.save();await api.refresh?.()}}
 function reply(text){const pending=[...api.getState().messages].reverse().find(m=>m.production?.status==='pending');if(!pending||productionIntent(text)||/^(нов|удал|обложк|озвуч|помоги|почему)/i.test(text))return false;const p=preferencesFromReply(text,pending.production.preferences);if(pending.production.request.kind==='script'&&!p.topic)p.topic=text.slice(0,1000);api.getState().messages.push({id:crypto.randomUUID(),role:'user',text});api.clearInput();execute(pending.id,p);return true;}
 function card(m){const job=m.production,box=el('section');box.className='production-card';box.setAttribute('aria-label','Задача видеопроизводства');const status=el('p',m.text);status.dataset.productionStatus=m.id;box.append(status);if(job.status==='done'){if(m.cover){const b=el('button','Посмотреть обложку');b.type='button';b.onclick=()=>api.openCover(m.cover);box.append(b)}return box;}if(job.status==='running'){const cancel=el('button','Остановить');cancel.onclick=()=>controller?.abort();box.append(cancel);return box;}let p=productionPreferences(job.preferences);const form=el('form'),grid=el('div');grid.className='production-grid';function select(label,key,values){const l=el('label',label),s=el('select');s.setAttribute('aria-label',label);for(const [v,t]of values){const o=el('option',t);o.value=v;s.append(o)}s.value=p[key];s.onchange=()=>{p[key]=s.value;job.preferences={...p};api.save()};l.append(s);grid.append(l)}
 select(job.request.kind==='speech'?'Язык речи (без перевода)':'Язык рекламного текста','language',[['ru','Русский'],['en','English']]);select('Оформление титров','style',[['karaoke','Reels — выделение слов'],['outline','Крупный текст с контуром'],['plate','Спокойная подложка'],['plain','Чистый текст']]);select('Шрифт','font',[['Roboto Condensed','Roboto Condensed'],['Golos Text','Golos Text']]);select('Положение титров','position',[['bottom','Снизу'],['center','В центре'],['top','Сверху']]);for(const [key,label]of [['color','Цвет текста'],['highlight','Цвет выделения']]){const l=el('label',label),input=el('input');input.type='color';input.value=p[key];input.setAttribute('aria-label',label);input.oninput=()=>{p[key]=input.value;job.preferences={...p};api.save();preview.style.color=p.color};l.append(input);grid.append(l)}const preview=el('div',p.language==='en'?'Your next story starts here':'Твоя история начинается здесь');preview.className='production-caption-preview';preview.style.color=p.color;form.append(grid,preview);
 if(job.request.kind==='script'){const l=el('label','Что рекламируем и для кого'),topic=el('textarea');topic.setAttribute('aria-label','Что рекламируем и для кого');topic.rows=2;topic.required=true;topic.placeholder='Товар, особенности, аудитория, призыв к действию. Цены — только известные.';topic.value=p.topic;topic.maxLength=1000;topic.onchange=()=>{p.topic=topic.value;job.preferences={...p};api.save()};l.append(topic);form.append(l);select('Палитра обложки','theme',[['auto','Подобрать по теме'],['automotive','Автомобили — графит и лайм'],['coffee','Кофейня — тёплые оттенки'],['technology','Технологии — холодные оттенки'],['travel','Путешествия — природные оттенки'],['editorial','Редакционная — нейтральная']]);const c=el('input');c.type='checkbox';c.checked=p.gradient;const label=el('label','Градиент на обложке');label.prepend(c);c.onchange=()=>p.gradient=c.checked;form.append(label);const visual=el('input');visual.type='checkbox';visual.checked=p.visualConsent;const vl=el('label','Передать выбранной модели уменьшенные кадры для анализа темы и обложки');vl.prepend(visual);visual.onchange=()=>p.visualConsent=visual.checked;form.append(vl,el('p',api.cost()));}else form.append(el('p','Whisper Small работает на устройстве. Первый запуск скачает модель (~270 МБ); аудио не отправляется на сервер, кредиты не списываются.'));
 const run=el('button',job.request.kind==='script'?'Создать монтаж, текст и обложку':'Распознать и оформить субтитры');run.type='submit';run.className='primary';form.onsubmit=e=>{e.preventDefault();execute(m.id,productionPreferences(p))};const skip=el('button','Отменить задачу');skip.type='button';skip.onclick=()=>{update(m.id,{production:{...job,status:'done'},text:'Задача отменена.'});api.render()};form.append(run,skip);box.append(form);return box;}
 return {queue,reply,card,isBusy:()=>busy};
}
